// src/App.js
import { useEffect, useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile
} from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [commitLabels, setCommitLabels] = useState([]);
  const [commitCounts, setCommitCounts] = useState([]);
  const [totalCommits, setTotalCommits] = useState(0);

  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Upload via dashboard");

  const [actionType, setActionType] = useState("commits"); // dropdown

  // ================= TOKEN =================
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const token = query.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ================= LOAD USER + REPOS =================
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // ================= FETCH COMMITS ONLY =================
  const fetchCommitHeatmap = async (payload) => {
    const commitRes = await fetchCommits(payload);

    const commitMap = {};
    commitRes.data.forEach(commit => {
      const date = commit.commit.committer.date.substring(0, 10);
      commitMap[date] = (commitMap[date] || 0) + 1;
    });

    const sortedDates = Object.keys(commitMap).sort();
    const sortedCounts = sortedDates.map(d => commitMap[d]);

    setCommitLabels(sortedDates);
    setCommitCounts(sortedCounts);
    setTotalCommits(sortedCounts.reduce((a, b) => a + b, 0));
  };

  // ================= TODAY =================
  const fetchToday = async () => {
    const today = new Date().toISOString().slice(0, 10);

    await fetchCommitHeatmap({
      owner,
      repo: selectedRepo,
      startDate: today,
      endDate: today
    });
  };

  // ================= ANALYZE =================
  const fetchData = async () => {
    if (actionType === "commits") {
  const res = await fetchCommits(payload);
  buildCommitHeatmap(res.data);
}

if (actionType === "prs") {
  const res = await fetchPRHeatmap(payload);
  buildGenericHeatmap(res.data);
}

if (actionType === "merge") {
  const res = await fetchMergeHeatmap(payload);
  buildGenericHeatmap(res.data);
}

    await fetchCommitHeatmap({
      owner,
      repo: selectedRepo,
      startDate,
      endDate
    });
  };

  // ================= UPLOAD =================
  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file");

    const reader = new FileReader();
    reader.onload = async () => {
      const base64Content = reader.result.split(",")[1];

      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        content: base64Content,
        message: uploadMessage
      });

      alert("✅ Uploaded to GitHub");
    };

    reader.readAsDataURL(selectedFile);
  };

  // ================= CHART =================
  const commitData = {
    labels: commitLabels,
    datasets: [
      {
        label: "Commits",
        data: commitCounts,
        backgroundColor: "#16A34A"
      }
    ]
  };

  // ================= UI =================
  return (
    <div style={styles.container}>
      <h1>GitHub Analytics Dashboard</h1>

      {!owner && (
        <button onClick={() => window.location.href =
          "http://localhost:8080/auth/github"}>
          Login with GitHub
        </button>
      )}

      {owner && <h3>Logged in as: {owner}</h3>}

      {owner && (
        <>
          {/* ================= CONTROL BAR ================= */}
          <div style={styles.form}>
            <select onChange={e => setSelectedRepo(e.target.value)}>
              {repos.map(repo => (
                <option key={repo.id} value={repo.name}>{repo.name}</option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <select onChange={(e) => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merge Files</option>
              <option value="clone">Clone Repo</option>
            </select>

            <button onClick={fetchData}>Analyze</button>
            <button onClick={fetchToday}>Today</button>
          </div>

          {/* ================= HEATMAP SECTION ================= */}
          {commitLabels.length > 0 && (
            <div style={styles.heatmapBox}>
              <div style={styles.topRightUpload}>
                <input type="file" onChange={e => setSelectedFile(e.target.files[0])} />
                <button onClick={handleUpload}>Upload</button>
              </div>

              <h3>Commit Activity Heatmap</h3>
              <Bar
                data={commitData}
                width={600}
                height={260}   // ✅ MEDIUM SIZE
                options={{ aspectRatio: 2.5 }}
              />
              <p>Total Commits: {totalCommits}</p>
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ================= STYLES =================
const styles = {
  container: {
    padding: 25,
    textAlign: "center",
    fontFamily: "Arial"
  },
  form: {
    display: "flex",
    justifyContent: "center",
    gap: 10,
    marginBottom: 20
  },
  heatmapBox: {
    width: "70%",
    margin: "auto",
    marginTop: 20,
    padding: 15,
    borderRadius: 12,
    background: "#F1F5F9",
    position: "relative"
  },
  topRightUpload: {
    position: "absolute",
    right: 10,
    top: 10,
    display: "flex",
    gap: 6
  }
};

export default App;
